                } else if (field.dtype().isChar()) {
                    int[] vector = MathEx.omit(
                            Arrays.stream(neighbors)
                                    .mapToInt(neighbor -> neighbor.key().getInt(i)).toArray(),
                            Integer.MIN_VALUE);
                    return vector.length == 0 ? null : (char) MathEx.mode(vector);
                } else if (field.measure() instanceof NominalScale) {
                    int[] vector = MathEx.omit(
                            Arrays.stream(neighbors)
                                    .mapToInt(neighbor -> neighbor.key().getInt(i)).toArray(),
                            Integer.MIN_VALUE);
                    return vector.length == 0 ? null : MathEx.mode(vector);
                } else if (field.dtype().isNumeric()) {
                    double[] vector = MathEx.omitNaN(
                            Arrays.stream(neighbors)
                                    .mapToDouble(neighbor -> neighbor.key().getDouble(i)).toArray());
                    return vector.length == 0 ? null : MathEx.mean(vector);
                } else {
                    return null;
                }
            }
        }
    };
}

 * @param k the number of eigenvectors used for imputation.
 * @param maxIter the maximum number of iterations.
 * @return the imputed data.
 * @throws IllegalArgumentException when the whole row or column is missing.
 */
static double[][] impute(double[][] data, int k, int maxIter) {
    if (k < 1 || k > Math.min(data.length, data[0].length)) {
        throw new IllegalArgumentException("Invalid number of eigenvectors for imputation: " + k);
    }

    if (maxIter < 1) {
        throw new IllegalArgumentException("Invalid maximum number of iterations: " + maxIter);
    }

    int d = data[0].length;
    double[][] full = SimpleImputer.impute(data);

    for (int iter = 0; iter < maxIter; iter++) {
        SVD svd = DenseMatrix.of(full).svd(true);

        for (int i = 0; i < data.length; i++) {
            int missing = 0;
            for (int j = 0; j < d; j++) {
                if (Double.isNaN(data[i][j])) {
                    missing++;
                } else {
                    full[i][j] = data[i][j];
                }
            }

            if (missing == 0) {
                continue;
            }

            DenseMatrix A = svd.Vt().zeros(d - missing, k);
            double[] b = new double[d - missing];

            for (int j = 0, m = 0; j < d; j++) {
                if (!Double.isNaN(data[i][j])) {
                    for (int l = 0; l < k; l++) {
                        A.set(m, l, svd.Vt().get(l, j));
                    }
                    b[m++] = data[i][j];
                }
            }

            QR qr = A.qr();
            Vector s = qr.solve(b);

            for (int j = 0; j < d; j++) {
                if (Double.isNaN(data[i][j])) {
                    full[i][j] = 0;
                    for (int l = 0; l < k; l++) {
                        full[i][j] += s.get(l) * svd.Vt().get(l, j);
                    }
                }
            }
        }
    }

    return full;

    public static double[][] impute(double[][] data) {
        int d = data[0].length;
        int[] count = new int[d];
        for (int i = 0; i < data.length; i++) {
            int missing = 0;
            for (int j = 0; j < d; j++) {
                if (Double.isNaN(data[i][j])) {
                    missing++;
                    count[j]++;
                }
            }

            if (missing == d) {
                throw new IllegalArgumentException("The whole row " + i + " is missing");
            }
        }

        for (int i = 0; i < d; i++) {
            if (count[i] == data.length) {
                throw new IllegalArgumentException("The whole column " + i + " is missing");
            }
        }

        double[] mean = new double[d];
        int[] n = new int[d];
        for (double[] x : data) {
            for (int j = 0; j < d; j++) {
                if (!Double.isNaN(x[j])) {
                    n[j]++;
                    mean[j] += x[j];
                }
            }
        }

        for (int j = 0; j < d; j++) {
            if (n[j] != 0) {
                mean[j] /= n[j];
            }
        }

        double[][] full = MathEx.clone(data);
        for (double[] x : full) {
            for (int j = 0; j < d; j++) {
                if (Double.isNaN(x[j])) {
                    x[j] = mean[j];
                }
            }
        }

        return full;
    }
}

